cssText:
.stage { background: linear-gradient(180deg, var(--void-top) 0%, var(--void) 58%); }
.hud-series { font-family: var(--font-display); text-transform: uppercase; letter-spacing: .14em; }
.hud-counter .v, .hud-scale, .hud-badge { font-variation-settings: "wdth" 100; font-variant-ligatures: no-contextual no-common-ligatures; }
.hud-badge { letter-spacing: .01em; }
